	["Más ira por cada golpe, sobre todo con armas rápidas."] = "공격마다 분노 증가, 특히 빠른 무기에서.",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "공격마다 분노 증가: 영웅의 일격과 죽음의 일격을 더 씁니다.",
	["Más ira por golpe."] = "공격마다 분노 증가.",
	["Más ira por golpe: más habilidades seguidas."] = "공격마다 분노 증가: 기술을 연달아 더 씁니다.",
