	["No"] = "끄기",
	["No compartes tu ubicación con tu hermandad."] = "길드와 위치를 공유하고 있지 않습니다.",
	["No encontramos a \"%s\" en tu grupo ni entre quienes comparten su ubicación."] = "파티나 위치 공유 중인 사람 중에 \"%s\" 님을 찾지 못했습니다.",
	["No encontré misiones de clase para ti ahora."] = "지금은 내 직업 퀘스트를 찾지 못했습니다.",
	["No encontré misiones que convenga dejar."] = "포기할 만한 퀘스트를 찾지 못했습니다.",
	["No encontré una mazmorra llamada «%s»."] = "«%s»(이)라는 던전을 찾지 못했습니다.",
	["No entregué %s: pide materiales de oficio. Entrégala tú si quieres."] = "%s 퀘스트를 제출하지 않았습니다: 전문 기술 재료가 필요합니다. 원하면 직접 제출하세요.",
	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "%s 퀘스트를 제출하지 않았습니다: 골드나 화폐가 필요합니다. 원하면 직접 제출하세요.",
	["No es para tu clase"] = "내 직업용 아님",
	["No está en tu árbol"] = "내 트리에 없음",
	["No estás en un grupo. Invita a alguien de la manada desde la lista de abajo."] = "파티에 속해 있지 않습니다. 아래 목록에서 무리의 누군가를 초대하세요.",
	["No estás en una hermandad. Mira la sección El clan para unirte a La Jauría."] = "길드에 속해 있지 않습니다. 클랜 항목을 보고 La Jauría에 가입하세요.",
	["No estás siguiendo a nadie."] = "아무도 따라가고 있지 않습니다.",
	["No hay botín a la vista todavía."] = "아직 표시할 전리품이 없습니다.",
	["No hay exactamente esa combinación. Te mostramos %s (%s), lo más parecido."] = "정확히 그 조합은 없습니다. 가장 비슷한 %s (%s)을(를) 보여 드립니다.",
	["No hay mazmorras que mostrar."] = "표시할 던전이 없습니다.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "찍을 것이 없습니다. 내 레벨까지의 계획을 이미 다 찍었거나 남은 포인트가 없습니다.",
	["No hay nodos conocidos en esta zona."] = "이 지역에 알려진 채집 지점이 없습니다.",
	["No hay otro addon de recolección activo."] = "활성화된 다른 채집 애드온이 없습니다.",
	["No hay un build con este estilo para lo que elegiste: Alfa usa el más cercano."] = "선택한 것에 이 스타일의 빌드가 없어 Alfa가 가장 가까운 빌드를 씁니다.",
	["No hay un camino que Alfa pueda guiar para este objeto (sale al azar o dentro de una mazmorra)."] = "Alfa가 안내할 수 있는 방법이 없는 아이템입니다(무작위로 떨어지거나 던전 안에서 나옵니다).",
	["No la usas"] = "사용 안 함",
	["No marcaste misiones para abandonar: toca la X de una misión."] = "포기할 퀘스트를 표시하지 않았습니다. 퀘스트의 X를 누르세요.",
	["No mostrar"] = "표시 안 함",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "아직 한참 남은 공격은 표시하지 않아 막대가 더 깔끔해집니다.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "이미 올 때가 됐지만 시점을 기다리는 공격은 표시하지 않습니다.",
	["No pegaste nada."] = "아무것도 붙여 넣지 않았습니다.",
	["No pude armar la ruta para tus misiones."] = "내 퀘스트로 경로를 만들지 못했습니다.",
	["No pude armar la ruta."] = "경로를 만들지 못했습니다.",
	["No pude leer dónde estás: las distancias son aproximadas."] = "현재 위치를 읽지 못해 거리는 대략적입니다.",
	["No queda ninguna misión en la ruta: quita algunas marcas."] = "경로에 남은 퀘스트가 없습니다. 표시를 일부 해제하세요.",
	["No quedan puntos libres."] = "남은 포인트가 없습니다.",
	["No sabemos dónde está %s. Solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "%s 님의 위치를 알 수 없습니다. 파티원과 Alfa로 위치를 공유하는 사람만 따라갈 수 있습니다.",
	["No sabemos dónde está: solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "위치를 알 수 없습니다. 파티원과 Alfa로 위치를 공유하는 사람만 따라갈 수 있습니다.",
	["No se aplicaron los talentos"] = "특성을 적용하지 못했습니다",
	["No se conoce botín propio de este jefe."] = "이 우두머리만의 전리품은 알려진 것이 없습니다.",
	["No se conoce la entrada de esta mazmorra."] = "이 던전의 입구를 알 수 없습니다.",
	["No se conoce ningún Alfa más reciente. La app de CurseForge o la página de versiones lo dicen con seguridad."] = "알려진 새 Alfa가 없습니다. 확실히 알려면 CurseForge 앱이나 릴리스 페이지를 확인하세요.",
	["No se encontraron los datos de las mazmorras (la carpeta Alfa_Codex). Reinstala Alfa completo."] = "던전 데이터(Alfa_Codex 폴더)를 찾을 수 없습니다. Alfa 전체를 다시 설치하세요.",
	["No se pudieron leer los datos del juego."] = "게임 데이터를 읽을 수 없습니다.",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Alfa Codex(아이템 데이터베이스)를 열 수 없습니다. Alfa Codex 애드온이 켜져 있는지 확인하세요.",
	["No se pudo armar la guía (%s)."] = "가이드를 만들 수 없습니다(%s).",
	["No se pudo comprar: %s"] = "찍지 못함: %s",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "스캔 결과를 읽을 수 없습니다. 나중에 다시 시도하세요.",
	["No se pudo probar ahora."] = "지금은 테스트할 수 없습니다.",
	["No se puede ordenar en combate."] = "전투 중에는 정렬할 수 없습니다.",
	["No se puede vender."] = "판매할 수 없습니다.",
	["No se sabe dónde está quien lo da o lo suelta."] = "주거나 떨어뜨리는 대상의 위치를 알 수 없습니다.",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "광산에 항상 나오지는 않습니다. 보이면 좋은 전리품을 주는 추가 우두머리입니다.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "항상 있지는 않습니다. 암흑 고통을 거니 걸린 사람을 치유하세요.",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "%s 퀘스트의 제출 장소를 몰라 경로에서 뺐습니다.",
	["No sé dónde se junta este material."] = "이 재료를 어디서 모으는지 모릅니다.",
	["No sé dónde se junta: búscalo en el catálogo para ver de dónde sale."] = "어디서 모으는지 모릅니다. 목록에서 찾아 출처를 확인하세요.",
	["No sé en qué zona estás."] = "현재 지역을 알 수 없습니다.",
	["No tienes misiones abiertas. ¡Todo libre!"] = "진행 중인 퀘스트가 없습니다. 모두 비었습니다!",
	["No tienes misiones que Alfa pueda guiar ahora."] = "지금 Alfa가 안내할 수 있는 퀘스트가 없습니다.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca hacia el nivel %d."] = "남은 포인트가 없습니다. 계획의 다음 특성(%s)은 %d레벨쯤에 찍게 됩니다.",
	["Noche"] = "밤",
	["Nodos ocultos."] = "채집 지점 숨김.",
	["Nodos visibles."] = "채집 지점 표시.",
