	["Objeto"] = "아이템",
	["Objeto %d"] = "아이템 %d",
	["Objetos de misión"] = "퀘스트 아이템",
	["Objetos nuevos"] = "새 아이템",
	["Objetos obtenidos"] = "획득한 아이템",
	["Oculta el botón con el número de addons en la esquina del minimapa. Esos addons se siguen abriendo con su comando, como /alfa."] = "미니맵 모서리에 있는 애드온 개수 버튼을 숨깁니다. 해당 애드온은 /alfa 같은 명령어로 계속 열 수 있습니다.",
	["Oculta el rastreador del juego a la derecha de la pantalla, con sus misiones, logros y profesiones. No con la interfaz de mando."] = "화면 오른쪽에 있는 게임 기본 추적기(퀘스트, 업적, 전문 기술 포함)를 숨깁니다. 게임패드 인터페이스에서는 작동하지 않습니다.",
	["Oculta lo que tu clase no puede usar o no le conviene."] = "내 직업이 쓸 수 없거나 맞지 않는 것을 숨깁니다.",
	["Oculta lo que tu clase no puede usar o no le conviene: armadura de otro tipo, armas que no usas, piezas sin nada para tu especialización."] = "내 직업이 쓸 수 없거나 맞지 않는 것을 숨깁니다: 다른 종류의 방어구, 쓰지 않는 무기, 내 전문화에 맞는 능력치가 없는 장비.",
	["Oculta los avisos que son para otro rol (por ejemplo, los del tanque si tú curas)."] = "다른 역할용 경고를 숨깁니다(예: 내가 치유 중이면 방어 전담용 경고).",
	["Oculta los mensajes de ataques que van contra otro jugador."] = "다른 플레이어를 노리는 공격 메시지를 숨깁니다.",
	["Ocultar ataques en espera"] = "대기 중인 공격 숨기기",
	["Ocultar cuentas largas"] = "긴 카운트다운 숨기기",
	["Ocultar el botín poco probable"] = "획득 확률 낮은 전리품 숨기기",
	["Ocultar el menú de addons"] = "애드온 메뉴 숨기기",
	["Ocultar la ventana de guía"] = "가이드 창 숨기기",
	["Ocultar lo de profesiones que no tienes"] = "내 전문 기술로 채집할 수 없는 것 숨기기",
	["Ocultar los botones de addons"] = "애드온 버튼 숨기기",
	["Ocultar los grifos de la barra de acción"] = "행동 단축바의 그리핀 숨기기",
	["Ocultar los marcos de grupo de Blizzard"] = "블리자드 파티 프레임 숨기기",
	["Ocultar nombres al pescar"] = "낚시 중 이름 숨기기",
	["Ocultarlo en combate"] = "전투 중 숨기기",
	["Ocultas"] = "숨김",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "게임처럼 숨기거나, 표시하거나, 가 보지 않은 곳을 알 수 있게 차가운 색조로 표시합니다.",
	["Oculto en el modelo."] = "모델에서 숨김.",
	["Oficiales: %s"] = "관리자: %s",
	["Oficios"] = "전문 기술",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "주의: 블리자드 클릭 시전이 이 클릭 중 %d개를 쓰고 있으며, 여기서도 그쪽이 우선합니다. 맞추려면 «블리자드 프레임에서도 사용»을 쓰세요.",
	["Olvidar"] = "삭제",
	["Olvidar a este personaje"] = "이 캐릭터 삭제",
	["Olvidar a quienes he visto"] = "내가 본 사람 목록 지우기",
	["Olvidar mi progreso aquí"] = "이곳 진행 상황 지우기",
	["Opcional"] = "선택",
