	["Orden"] = "순서",
	["Ordenar"] = "정렬",
	["Ordenar de derecha a izquierda"] = "오른쪽에서 왼쪽으로 정렬",
	["Oro"] = "골드",
	["Oro de hoy"] = "오늘의 골드",
	["Oro estimado: %s"] = "예상 골드: %s",
	["Oro neto por sesión"] = "세션별 순수익 골드",
	["Otras armas"] = "기타 무기",
	["Otro addon de pesca está activo"] = "다른 낚시 애드온 활성화됨",
	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "다른 낚시 애드온이 활성화되어 있습니다. 서로 충돌하지 않도록 Alfa 낚시는 일시 정지됩니다. 애드온 목록에서 둘 중 하나를 끄세요.",
	["Otro addon de recolección sigue activo: Alfa ya hace lo mismo, así que puedes desactivarlo para no ver los nodos dos veces."] = "다른 채집 애드온이 아직 활성화되어 있습니다. Alfa가 같은 일을 하므로, 채집 지점이 두 번 보이지 않게 그 애드온을 꺼도 됩니다.",
	["Otro golpe fuerte para tu rotación."] = "순환에 넣을 또 하나의 강한 공격.",
	["Otro golpe fuerte."] = "또 하나의 강한 공격.",
	["Otro material del catálogo..."] = "목록의 다른 재료...",
	["Otros"] = "기타",
	["Otros addons pueden poner puntos de ruta"] = "다른 애드온의 경유지 설정 허용",
	["PNJ %d"] = "NPC %d",
	["Paladín"] = "성기사",
	["Panel de estadísticas"] = "능력치 창",
	["Para abandonar"] = "포기 대상",
	["Para alguien de tu hermandad, agrega su rango."] = "같은 길드원이면 길드 등급을 추가합니다.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Alfa는 아이템마다 세 가지 방법을 비교합니다: 상인에게 팔기, 경매장에 올리기, 다른 것으로 바꾸기(아는 제조법이나 마력 추출로).",
	["Para mi nivel (±3)"] = "내 레벨용 (±3)",
	["Para mover la línea de tiempo o los mensajes: abre el menú del juego (Esc) y elige %s."] = "타임라인이나 경고 메시지를 옮기려면 게임 메뉴(Esc)를 열고 %s을(를) 고르세요.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "파티가 두 번 보이지 않게 합니다. 전투 중이 아닐 때 바뀝니다.",
	["Para pescar necesitas una caña en las manos. Cuando la tengas puesta, ya puedes lanzar."] = "낚시를 하려면 낚싯대를 손에 들어야 합니다. 장착하면 바로 던질 수 있습니다.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "서로 충돌하지 않도록 Alfa는 단축키를 가져가지 않고 설정도 바꾸지 않습니다. 애드온 목록(캐릭터 선택 화면)에서 둘 중 하나를 끄고 UI를 다시 불러오세요. Alfa를 남기면 다른 애드온에서 쓰던 키를 알아서 가져옵니다.",
	["Para que no dejes botín tirado por falta de espacio."] = "공간이 부족해 전리품을 두고 가는 일이 없도록 합니다.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "왼쪽 클릭으로 대상을 지정하고 싶은 분을 위한 설정입니다. 그 클릭의 치유 주문은 가운데 버튼으로 옮겨지고, 프리셋이 다시 적용됩니다.",
	["Para quien ya jugó esta mazmorra antes de instalar Alfa."] = "Alfa를 설치하기 전에 이 던전을 해 본 분을 위한 기능입니다.",
	["Para subir de nivel"] = "레벨 업까지",
	["Para tu %s"] = "내 %s",
	["Para tu nivel"] = "내 레벨용",
	["Para tu nivel (%d)"] = "내 레벨용 (%d)",
	["Para una montura mira el Buscador: dice qué nivel, equitación y oro pide."] = "탈것은 찾아보기에서 확인하세요. 필요한 레벨, 탈것 숙련, 골드를 알려 줍니다.",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "다시 쌓으려면 여관이나 마을에서 쉬세요(또는 접속을 종료하세요).",
	["Parada (%)"] = "무기 막기 (%)",
	["Parar"] = "무기 막기",
	["Paras más golpes de otros guerreros y pícaros."] = "다른 전사와 도적의 공격을 더 많이 막아 냅니다.",
	["Paras más golpes."] = "무기 막기가 늘어납니다.",
	["Paras más golpes: recibes menos daño desde el principio."] = "무기 막기가 늘어 처음부터 받는 피해가 줄어듭니다.",
	["Paras un poco más."] = "무기 막기가 조금 늘어납니다.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "공격을 무기로 막았습니다. 반격으로 적을 움직이지 못하게 합니다.",
	["Paraste un golpe: tu talento de contraataque está listo y desarma al enemigo."] = "공격을 무기로 막았습니다. 반격 특성을 쓸 수 있으며 적의 무장을 해제합니다.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "파티원에게 마우스를 올리고 클릭하세요: 왼쪽 클릭은 %s, 오른쪽 클릭은 %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "질병을 퍼뜨립니다. 직업이 해제할 수 있으면 해제하세요.",
	["Paso %d"] = "%d단계",
	["Paso %d de %d"] = "%d/%d단계",
	["Pasos que siguen, numerados"] = "다음 단계 번호 표시",
	["Pausa"] = "일시 정지",
	["Pecho"] = "가슴",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Alfa 경로 텍스트를 여기에 붙여 넣으세요(Ctrl+V).",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "ALFA1;로 시작하는 문자열을 여기에 붙여 넣고(Ctrl+V) 가져오기를 누르세요. Alfa가 모든 특성을 내 트리와 대조합니다.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "세게 때리지만 특별한 기술은 없습니다. 연습하기 좋은 우두머리입니다.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "세게 때리고 성스러운 빛의 보호막을 씁니다. 생명력을 가득 채우고 시작하세요.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "방어 전담을 연달아 여러 번 때립니다. 방어 전담의 생명력이 절반 아래로 떨어지지 않게 하세요.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "아주 세게 때립니다. 생명력을 가득 채우고 전투를 시작하세요.",
	["Pega primero una cadena de build de Alfa."] = "먼저 Alfa 빌드 문자열을 붙여 넣으세요.",
	["Pega primero una cadena de escala de estadísticas."] = "먼저 능력치 척도 문자열을 붙여 넣으세요.",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "공유된 곳에서 복사한 능력치 척도 문자열을 붙여 넣으세요(Ctrl+V).",
	["Pega varias veces seguidas: empieza con la vida llena."] = "연달아 여러 번 때립니다. 생명력을 가득 채우고 시작하세요.",
	["Pegas a dos: útil contra mascotas y grupos."] = "두 대상을 때립니다. 소환수와 무리를 상대할 때 유용합니다.",
	["Pegas más después de recibir críticos."] = "치명타를 맞은 뒤 더 세게 때립니다.",
	["Pegas más fuerte después de recibir críticos."] = "치명타를 맞은 뒤 더 세게 때립니다.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "치명타를 맞은 뒤 더 세게 때립니다.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "한 번에 몬스터 한 마리와 싸우세요. 두 마리가 오면 휩쓸기 일격을 쓰세요.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "항상 생명력을 가득 채우고 싸우세요. 쉬지 않고 몬스터를 연달아 상대하지 마세요.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "다른 플레이어와 싸우기: 버티고, 느리게 하고, 끝장내기.",
	["Peletería"] = "가죽세공",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "가죽세공으로 곰 변신에 쓸 방어도와 체력이 붙은 가죽을 만듭니다.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "가죽세공으로 내가 입을 사슬 갑옷을 만들고, 무두질로 골드 없이 재료를 얻습니다.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "가죽세공으로 민첩성과 체력이 붙은 가죽 장비를 만들고, 무두질로 가죽을 얻습니다.",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "공격마다 작은 아이콘을 붙입니다: 방어 전담용인지, 치유 전담용인지, 해제할 수 있는지, 치명적인지.",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "%s 님의 흔적을 놓쳤습니다. 더 이상 위치를 알 수 없습니다.",
	["Perjuicios que puedes quitar"] = "해제할 수 있는 약화 효과",
	["Permite lanzar con doble clic aunque vayas montado."] = "탈것을 타고 있어도 더블 클릭으로 던질 수 있습니다.",
	["Personaje"] = "캐릭터",
	["Pesca"] = "낚시",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Alfa 낚시 꺼짐. 단축키와 설정은 평소 그대로입니다.",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Alfa 낚시 켜짐. 단, 다른 낚시 애드온이 활성화된 동안은 일시 정지됩니다.",
	["Pesca de Alfa encendida."] = "Alfa 낚시 켜짐.",
	["Pescando"] = "낚시 중",
	["Pescando…"] = "낚시 중…",
	["Pescar: lanzar y recoger"] = "낚시: 던지기 및 낚아 올리기",
	["Pesos activos"] = "가중치 켜짐",
	["Pesos de %s activos: las flechas de mejora ya los usan."] = "%s 가중치 켜짐: 향상 화살표가 이미 사용 중입니다.",
	["Pesos de estadísticas"] = "능력치 가중치",
	["Pestaña nueva"] = "새 탭",
	["Pide al grupo que espere unos segundos antes de atacar."] = "공격하기 전에 몇 초 기다려 달라고 파티에 부탁하세요.",
	["Pide grupo"] = "파티 필요",
	["Pide grupo: hay élites."] = "파티 필요: 정예가 있습니다.",
	["Pidiendo los precios a la subasta..."] = "경매장에 가격을 요청하는 중...",
	["Piel o armadura demoníaca"] = "악마의 피부/갑옷",
	["Piernas"] = "다리",
	["Pies"] = "발",
	["Pinta del color de la clase el fondo del nombre en tu marco y en el del objetivo cuando es un jugador."] = "내 프레임과, 플레이어일 때의 대상 프레임에서 이름 배경을 직업 색상으로 칠합니다.",
	["Pizarra"] = "슬레이트",
	["Plantillas"] = "템플릿",
	["Pocos precios"] = "가격 적음",
	["Poder con hechizos"] = "주문력",
	["Poder de ataque"] = "전투력",
	["Poder de ataque a distancia"] = "원거리 전투력",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "상대에게 닿자마자 무력화를 걸고 계속 유지하세요.",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "지속 피해 주문을 모두 걸고 악마가 버티게 하세요.",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "몬스터가 다가오기 전에 보호막과 지속 피해를 걸어 두세요.",
	["Pon tus tótems al empezar cada pelea grande."] = "큰 전투를 시작할 때마다 토템을 세우세요.",
	["Pon un tótem antes de empezar la pelea."] = "전투를 시작하기 전에 토템을 세우세요.",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "전투를 시작하기 전에 덫을 놓고 몬스터를 그쪽으로 유인하세요.",
	["Pon venenos en tus armas siempre."] = "무기에 항상 독을 발라 두세요.",
	["Pone la flecha de Alfa en la entrada."] = "Alfa 화살표가 입구를 가리킵니다.",
	["Pone los marcos donde estaban al instalar Alfa."] = "프레임을 Alfa 설치 때의 위치로 되돌립니다.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos."] = "타임라인에 테스트 공격 세 개를 넣어 어디에 표시되는지 보여 줍니다. 저절로 사라집니다.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "받는 치유량을 줄이는 저주를 겁니다. 직업이 해제할 수 있으면 해제하세요.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "약화 저주와 서서히 타는 불을 겁니다. 가능하면 저주를 해제하세요.",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "파티 반대쪽으로 돌려세워 공격이 나에게만 맞게 하세요.",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "파티 반대쪽으로 돌려세우고 버티세요. 전투는 짧습니다.",
	["Ponlos al empezar a pelear."] = "전투를 시작할 때 세우세요.",
	["Ponte un escudo antes de empezar cada pelea."] = "전투를 시작할 때마다 보호막을 거세요.",
	["Por categorías"] = "분류별",
	["Por categorías agrupa tus cosas (equipo, consumibles, misiones...) con encabezados que se pliegan; una sola bolsa las muestra todas juntas, en su lugar."] = "분류별 보기는 장비, 소비용품, 퀘스트 아이템 등을 접을 수 있는 제목 아래로 묶습니다. 가방 하나 보기는 모든 것을 제자리에 한꺼번에 보여 줍니다.",
	["Por clase"] = "직업별",
	["Por grupo"] = "파티별",
	["Por jefe"] = "우두머리별",
	["Por mazmorra"] = "던전별",
	["Por nombre"] = "이름순",
	["Por rol"] = "역할별",
	["Por terminar"] = "진행 중",
	["Por zona (este personaje)"] = "지역별 (이 캐릭터)",
	["Porcentaje de vida"] = "생명력 백분율",
	["Posadas"] = "여관",
	["Posaderos; se marca el de tu piedra de hogar."] = "여관주인입니다. 귀환석이 묶인 곳의 여관주인은 따로 표시됩니다.",
	["Preajuste «%s» listo para tus clics."] = "«%s» 프리셋을 클릭에 적용했습니다.",
	["Preajustes listos para usar"] = "바로 쓰는 프리셋",
	["Precio de la subasta tomado de otro addon de subastas."] = "다른 경매장 애드온에서 가져온 경매장 가격입니다.",
	["Precios %s · %s objetos"] = "가격 %s · 아이템 %s개",
	["Precios al día"] = "가격 최신",
	["Precios viejos"] = "오래된 가격",
	["Precisión"] = "적중",
	["Precisión con hechizos"] = "주문 적중",
	["Preguntar"] = "물어보기",
	["Premio: %s"] = "보상: %s",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "타임라인, 도움 아이콘, 중간 및 위험 메시지를 켭니다.",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "블리자드 우두머리 경고 기능 전체(타임라인과 화면 메시지)를 켭니다. 이것이 꺼져 있으면 나머지도 보이지 않습니다.",
	["Prender el diario de mazmorras"] = "던전 도감 켜기",
	["Preparando el catálogo de objetos... %d%%"] = "아이템 목록 준비 중... %d%%",
	["Primer aviso"] = "첫 알림",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "먼저 경로를 만드세요: /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "방어 우선: 무기 막기가 훨씬 늘고 쉬는 시간이 줄어듭니다.",
	["Primero elige un tipo (por ejemplo, Armas)."] = "먼저 종류를 고르세요(예: 무기).",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "먼저 사령관 모그레인과 싸웁니다. 모그레인이 쓰러지면 그녀가 와서 부활시킵니다.",
	["Primero prende la línea de tiempo del jefe."] = "먼저 우두머리 타임라인을 켜세요.",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "먼저 벌목기가 나옵니다. 벌목기를 부수면 스니드가 내려와 걸어서 싸웁니다.",
	["Primeros auxilios"] = "응급치료",
	["Principal"] = "주",
	["Prioridad de estadísticas"] = "능력치 우선순위",
	["Probador"] = "미리보기 창",
	["Probar"] = "테스트",
	["Probar alerta"] = "알림 테스트",
	["Probar con 20"] = "20명으로 테스트",
	["Probar con 5"] = "5명으로 테스트",
	["Probar la línea de tiempo"] = "타임라인 테스트",
	["Probar un aviso"] = "알림 테스트",
	["Profesiones sugeridas"] = "추천 전문 기술",
	["Profesión"] = "전문 기술",
	["Promedio de la sesión: %s XP por hora."] = "세션 평균: 시간당 경험치 %s.",
	["Protección"] = "방어",
	["Protección para subir"] = "레벨업용 방어",
	["Proyectiles"] = "투사체",
	["Prueba"] = "테스트",
	["Prueba con %d: arrastra para mover"] = "%d명으로 테스트: 끌어서 이동",
	["Prueba de Alfa %d"] = "Alfa 테스트 %d",
	["Pruébala fuera de mazmorras y bandas."] = "던전과 공격대 밖에서 테스트하세요.",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "플레이어의 정신을 지배할 수 있습니다. 그 플레이어를 공격하지 말고 풀릴 때까지 기다리세요.",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "플레이어를 늑대인간으로 바꿀 수 있습니다. 그 플레이어를 공격하지 마세요. 저절로 풀립니다.",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "파티원 한 명을 재울 수 있습니다. 계속 싸우세요. 저절로 깨어납니다.",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "한 명을 재우고 주변 모두를 때릴 수 있습니다.",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "어퍼컷으로 날려 보냅니다. 치유 전담에게 가지 않도록 빨리 돌아오세요.",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "근접 플레이어를 짓밟을 수 있습니다. 근접 플레이어의 생명력을 높게 유지하세요.",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "방어 태세에서 돌진할 수 있어, 태세를 바꾸지 않고 방어 전담을 시작합니다.",
	["Puedes usarlo"] = "사용 가능",
	["Puedo usar"] = "사용 가능한 것만",
	["Pulsa %s para lanzar. Cuando el corcho se hunda, pulsa %s otra vez para recoger."] = "%s 키를 눌러 던지세요. 찌가 가라앉으면 %s 키를 다시 눌러 낚아 올리세요.",
	["Pulsa Guiarme para que la flecha te lleve."] = "'안내 시작'을 누르면 화살표가 안내합니다.",
	["Pulsa el botón para buscar. Tarda unos segundos la primera vez."] = "버튼을 누르면 검색합니다. 처음에는 몇 초 걸립니다.",
	["Puntería"] = "사격",
	["Puntería para subir"] = "레벨업용 사격",
	["Puntos de ruta"] = "경유지",
	["Puntos por gastar"] = "남은 포인트 있음",
	["Pícaro"] = "도적",
	["Quedan %s"] = "%s 남음",
	["Quiero unirme"] = "가입하고 싶어요",
	["Quieto"] = "서 있기",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "주 행동 단축바 양옆의 그리핀을 없앱니다. 편집 모드에도 이 기능을 위한 자체 설정이 있습니다.",
	["Quita los nodos que anotaste tú. La base incluida se queda."] = "내가 기록한 채집 지점을 지웁니다. 기본 제공 데이터베이스는 그대로 남습니다.",
	["Quitar (Alfa busca otra)"] = "빼기 (Alfa가 다른 것을 찾음)",
	["Quitar este tramo"] = "이 구간 빼기",
	["Quitar filtros"] = "필터 초기화",
	["Quitar la prueba"] = "테스트 종료",
	["Quiénes somos"] = "우리는 누구인가",
	["Qué es Alfa"] = "Alfa란?",
	["Qué mensajes mostrar"] = "표시할 메시지",
	["Qué muestran"] = "표시 정보",
	["Qué recolectar"] = "채집할 것",
	["Qué se envía: tu zona y posición en el mapa, tu nivel y tu clase. A quién: solo a tu hermandad y, si lo activas, a tus amigos con Alfa. Cuándo: cada 10 segundos mientras te mueves y cada 4 minutos si estás quieto. Nunca a canales públicos, nunca dentro de mazmorras. Lo que recibes de otros se borra solo a los 5 minutos."] = "보내는 정보: 지도상의 지역과 위치, 레벨, 직업. 받는 사람: 내 길드만, 그리고 켜면 Alfa를 쓰는 친구. 보내는 때: 움직이는 동안 10초마다, 가만히 있으면 4분마다. 공개 채널로는 절대 보내지 않고, 던전 안에서도 보내지 않습니다. 다른 사람에게 받은 정보는 5분 뒤 저절로 지워집니다.",
	["Qué se ve"] = "표시할 것",
	["Qué tan fuerte se oye el juego mientras el corcho está en el agua."] = "찌가 물에 떠 있는 동안의 게임 음량입니다.",
	["Qué tan grande se ve cada casilla."] = "각 칸의 크기입니다.",
	["Qué tan grande se ve el ícono de la sugerencia."] = "추천 아이콘의 크기입니다.",
	["Qué tomar y en qué orden"] = "무엇을 어떤 순서로 찍을지",
	["Rama:"] = "계열:",
	["Rango en tu hermandad:"] = "길드 등급:",
	["Ranura"] = "부위",
