	["Recientes"] = "최근",
	["Recoger todo lo que pesques"] = "낚은 것 모두 줍기",
	["Recoges hierbas por el camino y haces pociones de vida y maná: menos descanso y más seguridad."] = "가는 길에 약초를 캐서 생명력 물약과 마나 물약을 만듭니다. 덜 쉬고 더 안전합니다.",
	["Recolección"] = "채집",
	["Recolección: se trajeron %d nodos que recolectaste con otro addon."] = "채집: 다른 애드온으로 채집한 지점 %d곳을 가져왔습니다.",
	["Recomendada para ti"] = "나를 위한 추천",
