	["Recomendado por Alfa"] = "Alfa 추천",
	["Recomienda el camino que te deja más oro, si gana por lo menos un 10 % a venderlo. Si nada da oro, te dice que lo guardes. Alfa nunca vende ni compra por ti."] = "상인 판매보다 최소 10% 이상 더 벌 수 있을 때, 골드를 가장 많이 버는 방법을 추천합니다. 골드가 되는 방법이 없으면 보관하라고 알려 줍니다. Alfa는 절대 대신 팔거나 사지 않습니다.",
	["Recordatorios"] = "알림",
	["Recuperas maná incluso mientras peleas."] = "전투 중에도 마나를 회복합니다.",
	["Recuperas vida después de recibir críticos."] = "치명타를 맞은 뒤 생명력을 회복합니다.",
	["Recuperas vida después de recibir críticos: descansas menos."] = "치명타를 맞은 뒤 생명력을 회복해 덜 쉽니다.",
	["Recuperas vida poco a poco, incluso en combate."] = "전투 중에도 생명력을 조금씩 회복합니다.",
	["Recuperas vida y maná más rápido cuando no lanzas hechizos."] = "주문을 시전하지 않을 때 생명력과 마나를 더 빨리 회복합니다.",
	["Recurso"] = "자원",
	["Reduce el daño físico que recibes."] = "받는 물리 피해를 줄입니다.",
