	["Revancha fuerte desde temprano."] = "초반부터 강한 복수.",
	["Revancha más fuerte y puede aturdir."] = "더 강하고 기절시킬 수 있는 복수.",
	["Revancha pega fuerte y puede aturdir: tu golpe principal al subir."] = "복수가 세게 때리고 기절시킬 수 있습니다. 레벨업할 때 주력 공격입니다.",
	["Revancha pega más y puede aturdir: tu mejor golpe de amenaza."] = "복수가 더 세게 때리고 기절시킬 수 있습니다. 최고의 위협 공격입니다.",
	["Reveladas"] = "표시",
