	["Reverencia"] = "절하기",
	["Revisa miles de misiones para elegir las mejores: tarda unos segundos."] = "가장 좋은 퀘스트를 고르기 위해 수천 개를 살펴봅니다. 몇 초 걸립니다.",
	["Revisión rápida"] = "빠른 점검",
	["Reír"] = "웃기",
	["Ritmo: %s XP por hora; subes de nivel en %s."] = "속도: 시간당 경험치 %s, %s 후 레벨 업.",
	["Rueda del ratón: acercar o alejar donde está el cursor."] = "마우스 휠: 커서 위치를 기준으로 확대/축소.",
	["Rueda: acercar · Arrastra: mover · Doble clic: acercar · Mayús+clic: destino de la flecha"] = "휠: 확대/축소 · 끌기: 이동 · 더블 클릭: 확대 · Shift+클릭: 화살표 목적지",
	["Rugir"] = "포효",
