	["Ruta en el minimapa"] = "미니맵 경로",
	["Ruta en marcha: %s. Sigue la flecha."] = "경로 시작: %s. 화살표를 따라가세요.",
	["Ruta importada"] = "가져온 경로",
	["Ruta importada: %s."] = "경로를 가져왔습니다: %s.",
